/**
 * Header marking a route file as generated by the SMRT vite plugin.
 *
 * Shared by every route emitter (`sveltekit-generator.ts`,
 * `changes-route.ts`, `sync-apply-route.ts`, ...), so all emitters MUST use
 * the same constant — a divergent copy would orphan generated files. Whether
 * a file counts as generated is decided only by the predicate in
 * `generated-route-files.ts` (`isGeneratedRouteFile`), never by a local
 * comparison against this constant.
 */
export const AUTO_GENERATED_ROUTE_HEADER =
  '// Auto-generated by @smrt/core vite plugin';
